<script setup lang="ts">interface Option{label:string;value:string}interface Props{modelValue:string;options:Option[];label?:string;disabled?:boolean}defineProps<Props>();defineEmits<{(e:'update:modelValue',v:string):void}>()</script><template><label class="block space-y-1"><span v-if="label" class="text-sm">{{label}}</span><select :value="modelValue" class="w-full rounded border border-slate-300 px-3 py-2" :disabled="disabled" @change="$emit('update:modelValue', ($event.target as HTMLSelectElement).value)"><option v-for="option in options" :key="option.value" :value="option.value">{{option.label}}</option></select></label></template>
